import app from 'flarum/forum/app';
import FormModal from 'flarum/common/components/FormModal';
import Button from 'flarum/common/components/Button';
import extractText from 'flarum/common/utils/extractText';
import { t } from '../../common/api';
/**
 * Enter a photo. The preview is the browser's own reading of the file, so the
 * entrant sees what they chose; the server reads it again from scratch and
 * believes nothing the browser said about it.
 */
export default class SubmitModal extends FormModal {
  file = null;
  preview = null;
  photoTitle = '';
  caption = '';
  problem = null;
  className() {
    return 'ShutterSubmitModal Modal--medium';
  }
  title() {
    return t('submit.title');
  }
  onremove(vnode) {
    super.onremove(vnode);
    if (this.preview) URL.revokeObjectURL(this.preview);
  }
  pick(file) {
    this.problem = null;
    if (this.preview) URL.revokeObjectURL(this.preview);
    this.file = null;
    this.preview = null;
    if (!file) return;
    const maxMb = app.forum.attribute('shutterMaxMb') || 10;
    if (!/^image\/(jpeg|png|webp)$/.test(file.type)) {
      this.problem = extractText(t('submit.type'));
      return;
    }
    if (file.size > maxMb * 1024 * 1024) {
      this.problem = extractText(t('submit.too_big', {
        size: maxMb
      }));
      return;
    }
    this.file = file;
    this.preview = URL.createObjectURL(file);
    if (!this.photoTitle) this.photoTitle = file.name.replace(/\.[a-z0-9]+$/i, '').replace(/[_-]+/g, ' ').slice(0, 100);
  }
  content() {
    const c = this.attrs.gallery.contest;
    return m("div", {
      className: "Modal-body"
    }, c.rules ? m("p", {
      className: "ShutterSubmitModal-rules"
    }, c.rules) : null, m("label", {
      className: 'ShutterDrop' + (this.preview ? ' has-file' : '')
    }, m("input", {
      type: "file",
      accept: "image/jpeg,image/png,image/webp",
      className: "ShutterDrop-input",
      onchange: e => this.pick(e.target.files?.[0])
    }), this.preview ? m("img", {
      className: "ShutterDrop-preview",
      src: this.preview,
      alt: ""
    }) : m("span", {
      className: "ShutterDrop-hint"
    }, m("i", {
      className: "fas fa-image",
      "aria-hidden": "true"
    }), " ", t('submit.choose', {
      size: app.forum.attribute('shutterMaxMb') || 10
    }))), this.problem ? m("p", {
      className: "ShutterSubmitModal-problem"
    }, this.problem) : null, m("div", {
      className: "Form-group"
    }, m("label", {
      for: "shutter-title"
    }, t('submit.photo_title')), m("input", {
      id: "shutter-title",
      className: "FormControl",
      maxlength: 100,
      required: true,
      value: this.photoTitle,
      oninput: e => this.photoTitle = e.target.value
    })), m("div", {
      className: "Form-group"
    }, m("label", {
      for: "shutter-caption"
    }, t('submit.caption')), m("textarea", {
      id: "shutter-caption",
      className: "FormControl",
      maxlength: 500,
      rows: 3,
      value: this.caption,
      oninput: e => this.caption = e.target.value
    })), m("p", {
      className: "helpText"
    }, t('submit.privacy')), m("div", {
      className: "Form-group"
    }, m(Button, {
      type: "submit",
      className: "Button Button--primary Button--block",
      loading: this.loading,
      disabled: !this.file || !this.photoTitle.trim()
    }, t('submit.send'))));
  }
  onsubmit(e) {
    e.preventDefault();
    if (!this.file) return;
    const body = new FormData();
    body.append('photo', this.file);
    body.append('title', this.photoTitle.trim());
    body.append('caption', this.caption.trim());
    this.loading = true;
    app.request({
      method: 'POST',
      url: `${app.forum.attribute('apiUrl')}/shutter/contests/${this.attrs.gallery.id}/entries`,
      serialize: raw => raw,
      body
    }).then(() => {
      this.hide();
      this.attrs.gallery.view = 'all';
      this.attrs.gallery.sort = 'newest';
      this.attrs.gallery.load();
      app.alerts.show({
        type: 'success'
      }, t(this.attrs.gallery.contest.moderateEntries && !this.attrs.gallery.contest.canManage ? 'submit.pending' : 'submit.done'));
    }, error => {
      this.loading = false;
      this.onerror(error);
      m.redraw();
    });
  }
}
flarum.reg.add('ernestdefoe-shutter', 'forum/components/SubmitModal', SubmitModal);